const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const palmSprings = ee.Geometry.Point([-116.5453, 33.8303]);
    const startDate = '2017-06-15';
    const endDate = '2017-06-21';

    // 2. Data Acquisition & Check
    // Using MODIS Land Surface Temperature for daily coverage.
    let lstCollection = ee.ImageCollection('MODIS/061/MOD11A1')
        .filterDate(startDate, endDate)
        .filterBounds(palmSprings)
        .select(['LST_Day_1km', 'QC_Day']);

    const collectionSize = lstCollection.size().getInfo();
    if (collectionSize === 0) {
        console.log(`No MODIS images found for ${startDate} to ${endDate}.`);
        console.log('A: No'); // No data means the condition was not met by the data.
        return;
    }
    console.log(`Found ${collectionSize} MODIS images.`);

    // 3. Processing
    // Function to mask low-quality pixels and convert temperature to Fahrenheit.
    const processImage = function(image) {
        // According to MODIS QA documentation, bits 0-1 = '00' indicate good quality.
        const quality = image.select('QC_Day').bitwiseAnd(3).eq(0);
        const lstKelvin = image.select('LST_Day_1km').multiply(0.02);
        const lstFahrenheit = lstKelvin.subtract(273.15).multiply(9/5).add(32);
        return lstFahrenheit.updateMask(quality).rename('LST_Fahrenheit');
    };

    const processedCollection = lstCollection.map(processImage);

    // 4. Calculation
    // Find the maximum temperature over the time period for the region.
    const maxTempImage = processedCollection.max();

    const stats = maxTempImage.reduceRegion({
        reducer: ee.Reducer.max().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: palmSprings,
        scale: 1000,
        crs: 'EPSG:4326'
    });

    const maxTemp = stats.get('LST_Fahrenheit_max').getInfo();
    const pixelCount = stats.get('LST_Fahrenheit_count').getInfo();

    // 5. Validation & Final Answer
    if (pixelCount === 0) {
        console.log("No valid pixels found for Palm Springs after quality masking.");
        console.log("B: No"); // If no valid pixels, temp wasn't verifiably reached.
        return;
    }

    if (maxTemp === null || typeof maxTemp === 'undefined') {
        console.log("Calculation failed: could not retrieve a valid temperature value.");
        console.log("C3: Calculation Failure");
        return;
    }

    console.log(`Max observed surface temp: ${maxTemp.toFixed(2)} F`);
    console.log(`Valid pixels at location: ${pixelCount}`);

    if (maxTemp >= 115) {
        console.log("A: Yes");
    } else {
        console.log("B: No");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during Earth Engine initialization or analysis.');
        console.error(e);
        console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
    }
}

initEE();
